Lemma Zrange_forallb : forall (P : Z -> bool) (lo : Z) (n : nat),
  forallb P (map (fun k => lo + Z.of_nat k) (seq 0 n)) = true ->
  forall c, lo <= c < lo + Z.of_nat n -> P c = true.
Proof.
